import numpy as np

def mean_multiclass_dice(pred: np.ndarray, target: np.ndarray, num_classes: int, ignore_index=None) -> float:
    # Validate inputs
    if not isinstance(pred, np.ndarray) or not isinstance(target, np.ndarray):
        raise TypeError("pred and target must be numpy arrays")

    if pred.shape != target.shape:
        raise ValueError("pred and target must have the same shape")

    # Check for integer types
    if not np.issubdtype(pred.dtype, np.integer) or not np.issubdtype(target.dtype, np.integer):
        raise ValueError("pred and target must contain integer class IDs")

    # Validate class IDs are in range [0, num_classes - 1]
    if np.any(pred < 0) or np.any(pred >= num_classes):
        raise ValueError(f"pred contains class IDs outside range [0, {num_classes - 1}]")
    if np.any(target < 0) or np.any(target >= num_classes):
        raise ValueError(f"target contains class IDs outside range [0, {num_classes - 1}]")

    dice_scores = []

    for c in range(num_classes):
        # Skip ignored class
        if ignore_index is not None and c == ignore_index:
            continue

        pred_c = (pred == c)
        target_c = (target == c)

        # If class is absent in both prediction and target, skip it
        if not np.any(pred_c) and not np.any(target_c):
            continue

        intersection = np.logical_and(pred_c, target_c).sum()
        union = pred_c.sum() + target_c.sum()

        # Dice coefficient formula: 2 * |intersection| / (|pred| + |target|)
        # If union is 0, it means both are empty, but we already skipped that case.
        # However, if one is empty and the other is not, intersection is 0, union > 0, dice is 0.
        if union == 0:
            # This case is technically covered by the 'absent in both' check above,
            # but kept for safety.
            continue

        dice = (2.0 * intersection) / union
        dice_scores.append(dice)

    if len(dice_scores) == 0:
        return float('nan')

    return float(np.mean(dice_scores))
